input.command:
awk '
/^    \.\/run-server --data-dir/ { n++ ; if (n==2) {skipdup=2; next} }
skipdup==2 && /^    \.\/run-tests/ {skipdup=1; next}
skipdup==1 && /^$/ {skipdup=0; next}
{print}' README.md > /tmp/R.md && cp /tmp/R.md README.md && sed -i 's/^- `bin\/syncbox-server` — точка входа внутри контейнера\.$/- `bin\/syncbox-server` — точка входа сервера внутри контейнера./; s/^  на каждый запуск, проброс сигналов, `down` при выходе\.$/  на каждый запуск, проброс сигналов (клиенту — прямо в контейнер),\n  `down` при выходе./; s/^- `test\/` — minitest: юнит-тесты сервера (`test\/\*_test.rb`) и клиента (`test\/client\/`), интеграционные$/- `test\/` — minitest: юнит-тесты сервера (`test\/*_test.rb`) и клиента\n  (`test\/client\/`), интеграционные/' README.md && sed -n '8,16p;/^- `bin\/syncbox-server`/p;/^- `scripts/,$p' README.md

