25:      # byte by byte. "/" stays literal: it separates the key's segments.
26:      KEY_SAFE = %r{[A-Za-z0-9\-._~/]}
70:        encoded = key.b.gsub(/[^#{KEY_SAFE.source}]/n) { |byte| format("%%%02X", byte.ord) }

